def annotations_for(name: str) -> dict[str, Any]:
    """``name`` 的四项 hint（新副本）。未声明即 KeyError——静默默地全 false
    会让一个写工具在客户端看来可自动批准。"""
    try:
        hints = TOOL_ANNOTATIONS[name]
    except KeyError:
        raise KeyError(
            f"tool {name!r} has no entry in annotations.TOOL_ANNOTATIONS"
        ) from None
    return dict(hints)


def all_annotations() -> dict[str, dict[str, Any]]:
    """Every tool's hints (for tests / surface export)."""
    return {n: dict(h) for n, h in TOOL_ANNOTATIONS.items()}


__all__ = ["HINTS", "TOOL_ANNOTATIONS", "annotations_for", "all_annotations"]
